window.AUTH=window.AUTH||{};window.AUTH["88-493"]={"d":"88-493","id":"1989/88-493","n":"University of Pennsylvania v. Equal Employment Opportunity Commission","src":["osg"],"briefs":[{"k":"respondent","label":"Brief for the respondent","date":"","url":"https://www.justice.gov/osg/media/212456/dl?inline","side":"res","src":"osg","fmt":"Text","detail":"https://www.justice.gov/osg/brief/university-pennsylvania-petitioner-v-equal-employment-opportunity-commission-0","toa":false,"n":71}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep493/usrep493182/usrep493182.pdf","tr":false,"items":[{"t":"case","label":"EEOC v. Franklin & Marshall College","cite":"775 F.2d 110","y":1985,"url":"https://www.courtlistener.com/c/F.2d/775/110/","op":2,"by":{"0":""}},{"t":"case","label":"Hishon v. King & Spalding","cite":"467 U.S. 69","y":1984,"id":"1983/82-940","sc":1,"sum":"The Court held that Title VII makes it illegal for an employer to discriminate against any employee on the basis of their sex. In this case, the Court held that the promise of equal consideration for partnership that went along with Hishon’s employment was contractual in nature and subject to the regulations of Title VII.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"EEOC v. Shell Oil Co.","cite":"466 U.S. 54","y":1984,"id":"1983/82-825","sc":1,"op":4,"sum":"All of the strictures embodied in Title VII and the implementing regulation pertaining to the form and content of a charge of systemic discrimination and to the timing and adequacy of the notice afforded the employer were adhered to in this case, and therefore the EEOC was entitled to enforcement of its subpoena. Pp. 61-82. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Occidental Life Ins. Co. v. EEOC","cite":"432 U.S. 355","y":1977,"id":"1976/76-99","sc":1,"op":1,"sum":"About three years after an employee of petitioner company had first complained to the Equal Employment Opportunity Commission under Title VII of the Civil Rights Act of 1964 that petitioner had discriminated against her because of her sex, and five months after conciliation efforts by the EEOC had failed, the EEOC brought this enforcement action in the District Court for the Central District of California. The court …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Price Waterhouse v. Hopkins","cite":"109 S. Ct. 1775","y":1989,"id":"1988/87-1167","sc":1,"op":1,"sum":"The Supreme Court held that the court of appeals applied the right test, but should have placed the burden at “preponderance of the evidence” not “clear and convincing evidence”. On remand, Price Waterhouse would escape liability if it shows it would have denied Hopkins partnership even if she were not a woman.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Village of Arlington Heights v. Metropolitan Housing Development Corp.","cite":"429 U.S. 252","y":1977,"id":"1976/75-616","sc":1,"sum":"After finding that MHDC had proper federal standing, since it acted on behalf of black plaintiffs who stood to suffer direct and measurable injuries from Arlington's denial, the Court held that it failed to establish Arlington's racially discriminatory intent or purpose.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Upjohn v. United States","cite":"449 U.S. 383","y":1981,"id":"1980/79-886","sc":1,"sum":"When the General Counsel for petitioner pharmaceutical 'manufacturing corporation (hereafter petitioner) was informed that one of its foreign subsidiaries had made questionable payments to foreign government officials in order to secure government business, an internal investigation of such payments was initiated. As part of this investigation, petitioner's attorneys sent a questionnaire to all foreign managers …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"United States v. Euge","cite":"444 U.S. 707","y":1980,"id":"1979/78-1453","sc":1,"sum":"The IRS is empowered to compel handwriting exemplars under its summons authority conferred by § 7602.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Branzburg v. Hayes","cite":"408 U.S. 665","y":1972,"id":"1971/70-85","sc":1,"op":5,"sum":"The Court held that requiring reporters to testify before a grand jury does not violate freedom of press or speech in the First Amendment.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"DeBartolo Corp. v. Florida Gulf Coast Building and Construction Trades Council","cite":"485 U.S. 568","y":1988,"id":"1987/86-1461","sc":1,"sum":"The Court of Appeals did not err in construing § 8(b)(4) as not reaching respondent's handbilling. That construction makes it unnecessary to pass upon the serious First Amendment questions that would be raised by the Board's interpretation.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Public Citizen v. Department of Justice","cite":"109 S. Ct. 2558","y":1989,"url":"https://www.courtlistener.com/c/S.%20Ct./109/2558/","sc":1,"by":{"0":""}},{"t":"case","label":"City of Rome v. United States","cite":"446 U.S. 156","y":1980,"id":"1979/78-1840","sc":1,"sum":"In 1966, appellant city of Rome, Ga., made certain changes in its electoral system, including provisions for majority rather than plurality vote for each of the nine members of the City Commission; for three numbered posts within each of the three (reduced from nine) wards; and for staggered terms for the commissioners and for members of the Board of Education from each ward; and a requirement that members of the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Commodity Futures Trading Comm'n v. Schor","cite":"478 U.S. 833","y":1986,"id":"1985/85-621","sc":1,"sum":"Section 14 of the Commodity Exchange Act (CEA) provides that any person injured by a commodity broker's violation of the Act or regulations of the Commodity Futures Trading Commission (CFTC) may apply to the CFTC for an order directing the offender to pay reparations to the complainant and may enforce that order in federal district court. The CFTC promulgated a regulation that allows it in a reparations proceeding …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"St. Martin Lutheran Church v. South Dakota","cite":"451 U.S. 772","y":1981,"id":"1980/80-120","sc":1,"sum":"Petitioners are exempt from unemployment compensation taxes under § 3309 (b) (1) (A).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"International Ass'n of Machinists v. Street","cite":"367 U.S. 740","y":1961,"id":"1959/4","sc":1,"sum":"The Supreme Court held that the lower court did not need to decide the constitutionality of the union shop agreement. The Court remanded the case with suggestions for possible remedies. Justice William O. Douglas wrote a concurrence noting reservations about the suggested remedies. Justice Charles E. Whitaker concurred in part, but dissented to the suggestion of remedies.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Crowell v. Benson","cite":"285 U.S. 22","y":1932,"id":"scdb/1931-083","sc":1,"sum":"(1) As the claims are governed by the maritime law and within the admiralty jurisdiction, trial by jury is not required by the Seventh Amendment. P.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"NLRB v. Catholic Bishop","cite":"440 U.S. 490","y":1979,"id":"1978/77-752","sc":1,"sum":"Schools operated by a church to teach both religious and secular subjects are not within the jurisdiction granted by the National Labor Relations Act, and the NLRB was therefore without authority to issue the orders against respondents.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"McCulloch v. Sociedad Nacional de Marineros de Honduras","cite":"372 U.S. 10","y":1963,"id":"1962/107","sc":1,"sum":"The jurisdictional provisions of the National Labor Relations Act do not extend to the maritime operations of such foreign-flag ships employing alien seamen.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Sweezy v. New Hampshire","cite":"354 U.S. 234","y":1957,"id":"1956/175","sc":1,"op":3,"sum":"The appeal is dismissed. Treating the papers as a petition for certiorari under 28 U. S. C. § 2103, certiorari is granted.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Zahorik v. Cornell University","cite":"729 F.2d 85","y":1984,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/729/85/","by":{"0":""}},{"t":"case","label":"Runyon v. McCrary","cite":"427 U.S. 160","y":1976,"id":"1975/75-62","sc":1,"sum":"The Court held that Section 1981 prohibited the racially discriminatory policies of the schools.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Norwood v. Harrison","cite":"413 U.S. 455","y":1973,"id":"1972/72-77","sc":1,"sum":"A three-judge District Court sustained the validity of a Mississippi statutory program, begun in 1940, under which textbooks are purchased by the State and lent to students in both public and private schools, without reference to whether any participating private school has racially discriminatory policies. The number of private secular schools in Mississippi, with a virtually all-white student population, has …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"New York State Club Ass'n v. City of New York","cite":"108 S. Ct. 2225","y":1988,"id":"1987/86-1836","sc":1,"op":2,"sum":"The Court examined the clubs subjected to anti-discrimination laws closely and found \"no evidence of any club, let alone a substantial number of clubs, for whom the Law impairs the ability to associate or to advocate public or private viewpoints.\" In addition, many of the clubs showed characteristics of a public nature. Often strangers attended club functions, partook in meals, and made financial contributions.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Board of Directors of Rotary International v. Rotary Club of Duarte","cite":"481 U.S. 537","y":1987,"id":"1986/86-421","sc":1,"sum":"Considering the size, purpose, selectivity, and exclusivity of Rotary's membership, the Court found that the relationship among the club's members was not of the intimate or private variety which warrants First Amendment protection.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Roberts v. United States Jaycees","cite":"468 U.S. 609","y":1984,"id":"1983/83-724","sc":1,"sum":"The Court held that the Jaycees chapters lacked \"the distinctive characteristics that might afford constitutional protection to the decision of its members to exclude women.\" The Court reasoned that making women full members would not impose any serious burdens on the male members' freedom of expressive association.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Barenblatt v. United States","cite":"360 U.S. 109","y":1959,"id":"1958/35","sc":1,"sum":"The divided Court found that the Committee's actions did not violate the First Amendment and, thus, upheld Barenblatt's conviction for contempt of Congress. Justice Harlan noted that the First Amendment does not protect a witness from all lines of questioning. As long as the Congressional inquiry is pursued to \"aid the legislative process\" and to protect important government interests, then it is legitimate.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Regents of University of Michigan v. Ewing","cite":"474 U.S. 214","y":1985,"id":"1985/84-1273","sc":1,"op":1,"sum":"The Court held that, even if Ewing had a property interest in his admission, the careful consideration that went into his dismissal made this interference with his property anything but arbitrary. The Court determined that Ewing’s dismissal was reasonable based on all the available evidence.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Konigsberg v. State Bar","cite":"366 U.S. 36","y":1961,"id":"1960/28","sc":1,"sum":"Denial of petitioner's application for admission to the Bar on this ground did not violate his rights under the Fourteenth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Thornburgh v. American College of Obstetricians & Gynecologists","cite":"476 U.S. 747","y":1986,"id":"1985/84-495","sc":1,"sum":"In a 5-to-4 decision, the Court held that the Pennsylvania requirements \"wholly subordinate[d] constitutional privacy interests and concerns with maternal health\" and were attempts to deter women from making their own choices concerning abortion.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Gibson v. Florida Legislative Investigation Committee","cite":"372 U.S. 539","y":1963,"id":"1961/6","sc":1,"sum":"In a close decision, the Court found that Gibson's rights had been violated.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Shelton v. Tucker","cite":"364 U.S. 479","y":1960,"id":"1960/14","sc":1,"sum":"The statute is invalid, because it deprives teachers of their right of associational freedom protected by the Due Process Clause of the Fourteenth Amendment from invasion by state action.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Bates v. City of Little Rock","cite":"361 U.S. 516","y":1960,"id":"1959/41","sc":1,"sum":"On the record in this case, compulsory disclosure of the membership lists would work unjustified interference with the members' freedom of association, which is protected by the Due Process Clause of the Fourteenth Amendment from invasion by the States; and the convictions are reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"NAACP v. Alabama","cite":"357 U.S. 449","y":1958,"id":"1957/91","sc":1,"op":1,"sum":"The Court ruled that Alabama's requirement for the NAACP to divulge the names and addresses of all of its members and agents in the state violated the Due Process Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Buckley v. Valeo","cite":"424 U.S. 1","y":1976,"id":"1975/75-436","sc":1,"op":1,"sum":"The Court held that both upheld and struck down portions of the Federal Election Campaign Act of 1971. Restrictions on individual donations were not a violation of the donators' First Amendment rights; but certain restrictions of campaign expenditures did violate the First Amendment.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"EEOC v. Associated Dry Goods Corp.","cite":"449 U.S. 590","y":1981,"id":"1980/79-1068","sc":1,"op":1,"sum":"Congress did not include charging parties within the \"public\" to whom disclosure of confidential information is illegal under §§ 706 (b) and 709 (e).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Alexander v. Gardner-Denver Co.","cite":"415 U.S. 36","y":1974,"id":"1973/72-5847","sc":1,"sum":"An employee's statutory right to trial de novo under Title VII of the Civil Rights Act of 1964 is not foreclosed by prior submission of his claim to final arbitration under the nondiscrimination clause of a collective-bargaining.agreement.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Trammel v. United States","cite":"445 U.S. 40","y":1980,"id":"1979/78-5705","sc":1,"op":2,"sum":"The Court held that it is not eversible error to permit a wife to be called as a witness against her husband over his objection and without his consent.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"United States v. Bryan","cite":"339 U.S. 323","y":1950,"id":"scdb/1949-068","sc":1,"op":1,"sum":"Respondent was the executive secretary and had custody of the records of an association which was under investigation by the Committee on Un-American Activities of the House of Repre- - sentatives. The Committee issued and served upon respondent a subpoena directing her to produce before the Committee, at a stated time, specified records of the association. Respondent appeared before the Committee, but refused to …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Elkins v. United States","cite":"364 U.S. 206","y":1960,"id":"1959/126","sc":1,"sum":"1. Evidence obtained by state officers during a search which, if conducted by federal officers, would have violated the defendant's immunity from unreasonable searches and seizures under the Fourth Amendment is inadmissible over the defendant's timely objection in a federal criminal trial, even when there was no participation by federal officers in the search and seizure.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"United States v. Nixon","cite":"418 U.S. 683","y":1974,"id":"1973/73-1766","sc":1,"op":2,"sum":"The Court held that the President does not have executive privilege in immunity from subpoenas or other civil court actions.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Ibid. See NLRB v. Sears, Roebuck, & Co.","cite":"421 U.S. 132","id":"1974/73-1233","sc":1,"op":5,"sum":"Under the procedure for adjudicating unfair labor practice cases under the National Labor Relations Act, if a National Labor Relations Board (NLRB) Regional Director, with whom unfair labor practice charges are filed in the first instance and to whom the NLRB's General Counsel has delegated the initial power to decide whether or not to issue a complaint, believes that the charge has no merit, the charging party has …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Douglas Oil Co. v. Petrol Stops Northwest","cite":"441 U.S. 211","y":1979,"id":"1978/77-1547","sc":1,"op":2,"sum":"Respondents are independent gasoline dealers, one of which operates in Arizona and several other States, and two of which operate in the vicinity of Tucson, Ariz. They brought civil antitrust actions in the District Court in Arizona against several large oil companies, including petitioners. While these proceedings were in pretrial stages, a Government antitrust investigation in the Central District of California …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Similarly, Clark v. United States","cite":"289 U.S. 1","y":1933,"id":"scdb/1932-058","sc":1,"op":3,"sum":"1. Concealment or misstatement by a juror upon a voir dire examination is punishable as a contempt if its tendency and design are to obstruct the processes of justice. So held where the juror, on being asked to state her past employments, mentioned several but deliberately concealed an employment by the defendant, and on being questioned as to bias,, replied falsely that she had none,all with intent to gain a place …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"McKillop v. Regents of the University of California","cite":"386 F. Supp. 1270","y":1975,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp./386/1270/","by":{"0":""}},{"t":"case","label":"General Telephone Co. v. EEOC","cite":"446 U.S. 318","y":1980,"id":"1979/79-488","sc":1,"sum":"The EEOC may seek classwide relief under § 706 (f) (1) without being certified as the class representative under Rule 23.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Namenwirth v. Board of Regents","cite":"769 F.2d 1235","y":1985,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/769/1235/","by":{"0":""}},{"t":"case","label":"Sweeney v. Board of Trustees Keene State College","cite":"604 F.2d 106","y":1979,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/604/106/","by":{"0":""}},{"t":"case","label":"Gutzwiller v. Fenik","cite":"860 F.2d 1317","y":1988,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/860/1317/","by":{"0":""}},{"t":"case","label":"United States v. Morton Salt Co.","cite":"338 U.S. 632","y":1950,"id":"scdb/1949-040","sc":1,"sum":"Under § 5 of the Federal Trade Commission Act, the Commission ordered respondent corporations and others to cease and desist from certain trade practices. The Court of Appeals affirmed the order with modifications and commanded compliance. The decree directed that reports of compliance be filed with the Commission within 90 days, reserved jurisdiction to enter further orders to enforce compliance, and provided that …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"NLRB v. Martins Ferry Hospital Ass'n","cite":"649 F.2d 445","url":"https://www.courtlistener.com/c/F.2d/649/445/","by":{"0":""}},{"t":"case","label":"Board of Education v. Pico","cite":"457 U.S. 853","y":1982,"id":"1981/80-2043","sc":1,"sum":"The Court held that is is a violation of the First Amendment's freedom of speech protections for a Board of Education to ban books from public school libraries.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Healy v. James","cite":"408 U.S. 169","y":1972,"id":"1971/71-452","sc":1,"op":3,"sum":"Petitioners, seeking to form a local chapter of Students for a Democratic Society (SDS) at a state-supported college, were denied recognition as a campus organization. Recognition would have entitled petitioners to use campus facilities for meetings and to use of the campus bulletin board and school newspaper. The college president denied -recognition because he was not satisfied that petitioners' group was …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Keyishian v. Board of Regents","cite":"385 U.S. 589","y":1967,"id":"1966/105","sc":1,"op":4,"sum":"The Court held that the provisions of the New York plan were defined in such uncertain terms that they infringed upon the constitutional rights of public servants.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Cooper v. Ross","cite":"472 F. Supp. 802","y":1979,"court":"E.D. Ark.","url":"https://www.courtlistener.com/c/F.%20Supp./472/802/","by":{"0":""}},{"t":"case","label":"Lieberman v. Gant","cite":"630 F.2d 60","y":1980,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/630/60/","by":{"0":""}},{"t":"case","label":"Kunda v. Muhlenberg College","cite":"621 F.2d 532","y":1980,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/621/532/","by":{"0":""}},{"t":"case","label":"EEOC v. University of Notre Dame du Lac","cite":"715 F.2d 331","y":1983,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/715/331/","op":1,"by":{"0":""}},{"t":"case","label":"Gray v. Board of Higher Education","cite":"692 F.2d 901","y":1982,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/692/901/","by":{"0":""}},{"t":"case","label":"Lynn v. Regents of the University of California","cite":"656 F.2d 1337","y":1981,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/656/1337/","by":{"0":""}},{"t":"case","label":"Keyes v. Lenoir Rhyne College","cite":"552 F.2d 579","url":"https://www.courtlistener.com/c/F.2d/552/579/","by":{"0":""}},{"t":"case","label":"Pittsburgh Plate Glass Co. v. United States","cite":"360 U.S. 395","y":1959,"id":"1958/489","sc":1,"sum":"Under Ruie 6 (e) of the Federal Ruiles of Criminal Procedure the question whether the grand jury minutes should be produced was committed to the sound discretion of the trial judge; no abuse of his discretion has been shown; and petitioners' conviction is sustained.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"EEOC v. Tempel Steel Co.","cite":"814 F.2d 482","y":1987,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/814/482/","by":{"0":""}},{"t":"case","label":"EEOC v. A.E. Staley Mfg. Co.","cite":"711 F.2d 780","y":1983,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/711/780/","by":{"0":""}},{"t":"case","label":"EEOC v. Bay Shipbuilding Corp.","cite":"668 F.2d 304","y":1981,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/668/304/","by":{"0":""}},{"t":"case","label":"United States v. Gillock","cite":"445 U.S. 360","y":1980,"id":"1979/78-1455","sc":1,"op":1,"sum":"In a federal criminal prosecution against a state legislator there is no legislative privilege barring the introduction of evidence of the legislative acts of the legislator.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":""}},{"t":"usc","label":"42 U.S.C. § 2000e-5","url":"https://www.law.cornell.edu/uscode/text/42/2000e-5","subs":["(b)"],"stext":{"head":"§2000e–5. Enforcement provisions","paras":[[0,"(a) Power of Commission to prevent unlawful employment practices"],[0,"The Commission is empowered, as hereinafter provided, to prevent any person from engaging in any unlawful employment practice as set forth in section 2000e–2 or 2000e–3 of this title."],[0,"(b) Charges by persons aggrieved or member of Commission of unlawful employment practices by employers, etc.; filing; allegations; notice to respondent; contents of notice; investigation by Commission; contents of charges; prohibition on disclosure of charges; determination of reasonable cause; conference, conciliation, and persuasion for elimination of unlawful practices; prohibition on disclosure of informal endeavors to end unlawful practices; use of evidence in subsequent proceedings; penalties for disclosure of information; time for determination of reasonable cause"],[0,"Whenever a charge is filed by or on behalf of a person claiming to be aggrieved, or by a member of the Commission, alleging that an employer, employment agency, labor organization, or joint labor-management committee controlling apprenticeship or other training or retraining, including on-the-job training programs, has engaged in an unlawful employment practice, the Commission shall serve a notice of the charge (including the date, place and circumstances of the alleged unlawful employment practice) on such employer, employment agency, labor organization, or joint labor-management committee (hereinafter referred to as the \"respondent\") within ten days, and shall make an investigation thereof. Charges shall be in writing under oath or affirmation and shall contain such information and be in such form as the Commission requires. Charges shall not be made public by the Commission. If the Commission determines after such investigation that there is not reasonable cause to believe that the charge is true, it shall dismiss the charge and promptly notify the person claiming to be aggrieved and the respondent of its action. In determining whether reasonable cause exists, the Commission shall accord substantial weight to final findings and orders made by State or local authorities in proceedings commenced under State or local law pursuant to the requirements of subsections (c) and (d). If the Commission determines after such investigation that there is reasonable cause to believe that the charge is true, the Commission shall endeavor to eliminate any such alleged unlawful employment practice by informal methods of conference, conciliation, and persuasion. Nothing said or done during and as a part of such informal endeavors may be made public by the Commission, its officers or employees, or used as evidence in a subsequent proceeding without the written consent of the persons concerned. Any person who makes public information in violation of this subsection shall be fined not more than $1,000 or imprisoned for not more than one year, or both. The Commission shall make its determination on reasonable cause as promptly as possible and, so far as practicable, not later than one hundred and twenty days from the filing of the charge or, where applicable under subsection (c) or (d), from the date upon which the Commission is authorized to take action with respect to the charge."],[0,"(c) State or local enforcement proceedings; notification of State or local authority; time for filing charges with Commission; commencement of proceedings"],[0,"In the case of an alleged unlawful employment practice occurring in a State, or political subdivision of a State, which has a State or local law prohibiting the unlawful employment practice alleged and establishing or authorizing a State or local authority to grant or seek relief from such practice or to institute criminal proceedings with respect thereto upon receiving notice thereof, no charge may be filed under subsection (a) 1 by the person aggrieved before the expiration of sixty days after proceedings have been commenced under the State or local law, unless such proceedings have been earlier terminated, provided that such sixty-day period shall be extended to one hundred and twenty days during the first year after the effective date of such State or local law. If any requirement for the commencement of such proceedings is imposed by a State or local authority other than a requirement of the filing of a written and signed statement of the facts upon which the proceeding is based, the proceeding shall be deemed to have been commenced for the purposes of this subsection at the time such statement is sent by registered mail to the appropriate State or local authority."],[0,"(d) State or local enforcement proceedings; notification of State or local authority; time for action on charges by Commission"],[0,"In the case of any charge filed by a member of the Commission alleging an unlawful employment practice occurring in a State or political subdivision of a State which has a State or local law prohibiting the practice alleged and establishing or authorizing a State or local authority to grant or seek relief from such practice or to institute criminal proceedings with respect thereto upon receiving notice thereof, the Commission shall, before taking any action with respect to such charge, notify the appropriate State or local officials and, upon request, afford them a reasonable time, but not less than sixty days (provided that such sixty-day period shall be extended to one hundred and twenty days during the first year after the effective day of such State or local law), unless a shorter period is requested, to act under such State or local law to remedy the practice alleged."],[0,"(e) Time for filing charges; time for service of notice of charge on respondent; filing of charge by Commission with State or local agency; seniority system"],[0,"(1) A charge under this section shall be filed within one hundred and eighty days after the alleged unlawful employment practice occurred and notice of the charge (including the date, place and circumstances of the alleged unlawful employment practice) shall be served upon the person against whom such charge is made within ten days thereafter, except that in a case of an unlawful employment practice with respect to which the person aggrieved has initially instituted proceedings with a State or local agency with authority to grant or seek relief from such practice or to institute criminal proceedings with respect thereto upon receiving notice thereof, such charge shall be filed by or on behalf of the person aggrieved within three hundred days after the alleged unlawful employment practice occurred, or within thirty days after receiving notice that the State or local agency has terminated the proceedings under the State or local law, whichever is earlier, and a copy of such charge shall be filed by the Commission with the State or local agency."],[0,"(2) For purposes of this section, an unlawful employment practice occurs, with respect to a seniority system that has been adopted for an intentionally discriminatory purpose in violation of this subchapter (whether or not that discriminatory purpose is apparent on the face of the seniority provision), when the seniority system is adopted, when an individual becomes subject to the seniority system, or when a person aggrieved is injured by the application of the seniority system or provision of the system."],[0,"(3)(A) For purposes of this section, an unlawful employment practice occurs, with respect to discrimination in compensation in violation of this subchapter, when a discriminatory compensation decision or other practice is adopted, when an individual becomes subject to a discriminatory compensation decision or other practice, or when an individual is affected by application of a discriminatory compensation decision or other practice, including each time wages, benefits, or other compensation is paid, resulting in whole or in part from such a decision or other practice."],[0,"(B) In addition to any relief authorized by section 1981a of this title, liability may accrue and an aggrieved person may obtain relief as provided in subsection (g)(1), including recovery of back pay for up to two years preceding the filing of the charge, where the unlawful employment practices that have occurred during the charge filing period are similar or related to unlawful employment practices with regard to discrimination in compensation that occurred outside the time for filing a charge."],[0,"(f) Civil action by Commission, Attorney General, or person aggrieved; preconditions; procedure; appointment of attorney; payment of fees, costs, or security; intervention; stay of Federal proceedings; action for appropriate temporary or preliminary relief pending final disposition of charge; jurisdiction and venue of United States courts; designation of judge to hear and determine case; assignment of case for hearing; expedition of case; appointment of master"],[0,"(1) If within thirty days after a charge is filed with the Commission or within thirty days after expiration of any period of reference under subsection (c) or (d), the Commission has been unable to secure from the respondent a conciliation agreement acceptable to the Commission, the Commission may bring a civil action against any respondent not a government, governmental agency, or political subdivision named in the charge. In the case of a respondent which is a government, governmental agency, or political subdivision, if the Commission has been unable to secure from the respondent a conciliation agreement acceptable to the Commission, the Commission shall take no further action and shall refer the case to the Attorney General who may bring a civil action against such respondent in the appropriate United States district court. The person or persons aggrieved shall have the right to intervene in a civil action brought by the Commission or the Attorney General in a case involving a government, governmental agency, or political subdivision. If a charge filed with the Commission pursuant to subsection (b), is dismissed by the Commission, or if within one hundred and eighty days from the filing of such charge or the expiration of any period of reference under subsection (c) or (d), whichever is later, the Commission has not filed a civil action under this section or the Attorney General has not filed a civil action in a case involving a government, governmental agency, or political subdivision, or the Commission has not entered into a conciliation agreement to which the person aggrieved is a party, the Commission, or the Attorney General in a case involving a government, governmental agency, or political subdivision, shall so notify the person aggrieved and within ninety days after the giving of such notice a civil action may be brought against the respondent named in the charge (A) by the person claiming to be aggrieved or (B) if such charge was filed by a member of the Commission, by any person whom the charge alleges was aggrieved by the alleged unlawful employment practice. Upon application by the complainant and in such circumstances as the court may deem just, the court may appoint an attorney for such complainant and may authorize the commencement of the action without the payment of fees, costs, or security. Upon timely application, the court may, in its discretion, permit the Commission, or the Attorney General in a case involving a government, governmental agency, or political subdivision, to intervene in such civil action upon certification that the case is of general public importance. Upon request, the court may, in its discretion, stay further proceedings for not more than sixty days pending the termination of State or local proceedings described in subsection (c) or (d) of this section or further efforts of the Commission to obtain voluntary compliance."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e-5?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2000e–5. Enforcement provisions","tname":"The Public Health and Welfare","by":{"0":""}},{"t":"usc","label":"29 U.S.C. § 161","url":"https://www.law.cornell.edu/uscode/text/29/161","stext":{"head":"§161. Investigatory powers of Board","paras":[[0,"For the purpose of all hearings and investigations, which, in the opinion of the Board, are necessary and proper for the exercise of the powers vested in it by sections 159 and 160 of this title—"],[0,"(1) Documentary evidence; summoning witnesses and taking testimony"],[1,"The Board, or its duly authorized agents or agencies, shall at all reasonable times have access to, for the purpose of examination, and the right to copy any evidence of any person being investigated or proceeded against that relates to any matter under investigation or in question. The Board, or any member thereof, shall upon application of any party to such proceedings, forthwith issue to such party subpenas requiring the attendance and testimony of witnesses or the production of any evidence in such proceedings or investigation requested in such application. Within five days after the service of a subpena on any person requiring the production of any evidence in his possession or under his control, such person may petition the Board to revoke, and the Board shall revoke, such subpena if in its opinion the evidence whose production is required does not relate to any matter under investigation, or any matter in question in such proceedings, or if in its opinion such subpena does not describe with sufficient particularity the evidence whose production is required. Any member of the Board, or any agent or agency designated by the Board for such purposes, may administer oaths and affirmations, examine witnesses, and receive evidence. Such attendance of witnesses and the production of such evidence may be required from any place in the United States or any Territory or possession thereof, at any designated place of hearing."],[0,"(2) Court aid in compelling production of evidence and attendance of witnesses"],[1,"In case of contumacy or refusal to obey a subpena issued to any person, any district court of the United States or the United States courts of any Territory or possession, within the jurisdiction of which the inquiry is carried on or within the jurisdiction of which said person guilty of contumacy or refusal to obey is found or resides or transacts business, upon application by the Board shall have jurisdiction to issue to such person an order requiring such person to appear before the Board, its member, agent, or agency, there to produce evidence if so ordered, or there to give testimony touching the matter under investigation or in question; and any failure to obey such order of the court may be punished by said court as a contempt thereof."],[0,"(3) Repealed. Pub. L. 91–452, title II, §234, Oct. 15, 1970, 84 Stat. 930"],[0,"(4) Process, service and return; fees of witnesses"],[1,"Complaints, orders, and other process and papers of the Board, its member, agent, or agency, may be served either personally or by registered or certified mail or by telegraph or by leaving a copy thereof at the principal office or place of business of the person required to be served. The verified return by the individual so serving the same setting forth the manner of such service shall be proof of the same, and the return post office receipt or telegraph receipt therefor when registered or certified and mailed or when telegraphed as aforesaid shall be proof of service of the same. Witnesses summoned before the Board, its member, agent, or agency, shall be paid the same fees and mileage that are paid witnesses in the courts of the United States, and witnesses whose depositions are taken and the persons taking the same shall severally be entitled to the same fees as are paid for like services in the courts of the United States."],[0,"(5) Process, where served"],[1,"All process of any court to which application may be made under this subchapter may be served in the judicial district wherein the defendant or other person required to be served resides or may be found."],[0,"(6) Information and assistance from departments"],[1,"The several departments and agencies of the Government, when directed by the President, shall furnish the Board, upon its request, all records, papers, and information in their possession relating to any matter before the Board."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/161?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§161. Investigatory powers of Board","tname":"Labor","by":{"0":""}},{"t":"usc","label":"42 U.S.C. § 2000e-9","url":"https://www.law.cornell.edu/uscode/text/42/2000e-9","stext":{"head":"§2000e–9. Conduct of hearings and investigations pursuant to section 161 of title 29","paras":[[0,"For the purpose of all hearings and investigations conducted by the Commission or its duly authorized agents or agencies, section 161 of title 29 shall apply."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e-9?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2000e–9. Conduct of hearings and investigations pursuant to section 161 of title 29","tname":"The Public Health and Welfare","by":{"0":""}},{"t":"usc","label":"42 U.S.C. § 2000e-2","url":"https://www.law.cornell.edu/uscode/text/42/2000e-2","subs":["(a)"],"stext":{"head":"§2000e–2. Unlawful employment practices","paras":[[0,"(a) Employer practices"],[0,"It shall be an unlawful employment practice for an employer—"],[1,"(1) to fail or refuse to hire or to discharge any individual, or otherwise to discriminate against any individual with respect to his compensation, terms, conditions, or privileges of employment, because of such individual's race, color, religion, sex, or national origin; or"],[1,"(2) to limit, segregate, or classify his employees or applicants for employment in any way which would deprive or tend to deprive any individual of employment opportunities or otherwise adversely affect his status as an employee, because of such individual's race, color, religion, sex, or national origin."],[0,"(b) Employment agency practices"],[0,"It shall be an unlawful employment practice for an employment agency to fail or refuse to refer for employment, or otherwise to discriminate against, any individual because of his race, color, religion, sex, or national origin, or to classify or refer for employment any individual on the basis of his race, color, religion, sex, or national origin."],[0,"(c) Labor organization practices"],[0,"It shall be an unlawful employment practice for a labor organization—"],[1,"(1) to exclude or to expel from its membership, or otherwise to discriminate against, any individual because of his race, color, religion, sex, or national origin;"],[1,"(2) to limit, segregate, or classify its membership or applicants for membership, or to classify or fail or refuse to refer for employment any individual, in any way which would deprive or tend to deprive any individual of employment opportunities, or would limit such employment opportunities or otherwise adversely affect his status as an employee or as an applicant for employment, because of such individual's race, color, religion, sex, or national origin; or"],[1,"(3) to cause or attempt to cause an employer to discriminate against an individual in violation of this section."],[0,"(d) Training programs"],[0,"It shall be an unlawful employment practice for any employer, labor organization, or joint labor-management committee controlling apprenticeship or other training or retraining, including on-the-job training programs to discriminate against any individual because of his race, color, religion, sex, or national origin in admission to, or employment in, any program established to provide apprenticeship or other training."],[0,"(e) Businesses or enterprises with personnel qualified on basis of religion, sex, or national origin; educational institutions with personnel of particular religion"],[0,"Notwithstanding any other provision of this subchapter, (1) it shall not be an unlawful employment practice for an employer to hire and employ employees, for an employment agency to classify, or refer for employment any individual, for a labor organization to classify its membership or to classify or refer for employment any individual, or for an employer, labor organization, or joint labor-management committee controlling apprenticeship or other training or retraining programs to admit or employ any individual in any such program, on the basis of his religion, sex, or national origin in those certain instances where religion, sex, or national origin is a bona fide occupational qualification reasonably necessary to the normal operation of that particular business or enterprise, and (2) it shall not be an unlawful employment practice for a school, college, university, or other educational institution or institution of learning to hire and employ employees of a particular religion if such school, college, university, or other educational institution or institution of learning is, in whole or in substantial part, owned, supported, controlled, or managed by a particular religion or by a particular religious corporation, association, or society, or if the curriculum of such school, college, university, or other educational institution or institution of learning is directed toward the propagation of a particular religion."],[0,"(f) Members of Communist Party or Communist-action or Communist-front organizations"],[0,"As used in this subchapter, the phrase \"unlawful employment practice\" shall not be deemed to include any action or measure taken by an employer, labor organization, joint labor-management committee, or employment agency with respect to an individual who is a member of the Communist Party of the United States or of any other organization required to register as a Communist-action or Communist-front organization by final order of the Subversive Activities Control Board pursuant to the Subversive Activities Control Act of 1950 [50 U.S.C. 781 et seq.]."],[0,"(g) National security"],[0,"Notwithstanding any other provision of this subchapter, it shall not be an unlawful employment practice for an employer to fail or refuse to hire and employ any individual for any position, for an employer to discharge any individual from any position, or for an employment agency to fail or refuse to refer any individual for employment in any position, or for a labor organization to fail or refuse to refer any individual for employment in any position, if—"],[1,"(1) the occupancy of such position, or access to the premises in or upon which any part of the duties of such position is performed or is to be performed, is subject to any requirement imposed in the interest of the national security of the United States under any security program in effect pursuant to or administered under any statute of the United States or any Executive order of the President; and"],[1,"(2) such individual has not fulfilled or has ceased to fulfill that requirement."],[0,"(h) Seniority or merit system; quantity or quality of production; ability tests; compensation based on sex and authorized by minimum wage provisions"],[0,"Notwithstanding any other provision of this subchapter, it shall not be an unlawful employment practice for an employer to apply different standards of compensation, or different terms, conditions, or privileges of employment pursuant to a bona fide seniority or merit system, or a system which measures earnings by quantity or quality of production or to employees who work in different locations, provided that such differences are not the result of an intention to discriminate because of race, color, religion, sex, or national origin, nor shall it be an unlawful employment practice for an employer to give and to act upon the results of any professionally developed ability test provided that such test, its administration or action upon the results is not designed, intended or used to discriminate because of race, color, religion, sex or national origin. It shall not be an unlawful employment practice under this subchapter for any employer to differentiate upon the basis of sex in determining the amount of the wages or compensation paid or to be paid to employees of such employer if such differentiation is authorized by the provisions of section 206(d) of title 29."],[0,"(i) Businesses or enterprises extending preferential treatment to Indians"],[0,"Nothing contained in this subchapter shall apply to any business or enterprise on or near an Indian reservation with respect to any publicly announced employment practice of such business or enterprise under which a preferential treatment is given to any individual because he is an Indian living on or near a reservation."],[0,"(j) Preferential treatment not to be granted on account of existing number or percentage imbalance"],[0,"Nothing contained in this subchapter shall be interpreted to require any employer, employment agency, labor organization, or joint labor-management committee subject to this subchapter to grant preferential treatment to any individual or to any group because of the race, color, religion, sex, or national origin of such individual or group on account of an imbalance which may exist with respect to the total number or percentage of persons of any race, color, religion, sex, or national origin employed by any employer, referred or classified for employment by any employment agency or labor organization, admitted to membership or classified by any labor organization, or admitted to, or employed in, any apprenticeship or other training program, in comparison with the total number or percentage of persons of such race, color, religion, sex, or national origin in any community, State, section, or other area, or in the available work force in any community, State, section, or other area."],[0,"(k) Burden of proof in disparate impact cases"],[0,"(1)(A) An unlawful employment practice based on disparate impact is established under this subchapter only if—"],[1,"(i) a complaining party demonstrates that a respondent uses a particular employment practice that causes a disparate impact on the basis of race, color, religion, sex, or national origin and the respondent fails to demonstrate that the challenged practice is job related for the position in question and consistent with business necessity; or"],[1,"(ii) the complaining party makes the demonstration described in subparagraph (C) with respect to an alternative employment practice and the respondent refuses to adopt such alternative employment practice."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e-2?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2000e–2. Unlawful employment practices","tname":"The Public Health and Welfare","by":{"0":""}},{"t":"usc","label":"42 U.S.C. § 2000e-8","url":"https://www.law.cornell.edu/uscode/text/42/2000e-8","subs":["(a)"],"stext":{"head":"§2000e–8. Investigations","paras":[[0,"(a) Examination and copying of evidence related to unlawful employment practices"],[0,"In connection with any investigation of a charge filed under section 2000e–5 of this title, the Commission or its designated representative shall at all reasonable times have access to, for the purposes of examination, and the right to copy any evidence of any person being investigated or proceeded against that relates to unlawful employment practices covered by this subchapter and is relevant to the charge under investigation."],[0,"(b) Cooperation with State and local agencies administering State fair employment practices laws; participation in and contribution to research and other projects; utilization of services; payment in advance or reimbursement; agreements and rescission of agreements"],[0,"The Commission may cooperate with State and local agencies charged with the administration of State fair employment practices laws and, with the consent of such agencies, may, for the purpose of carrying out its functions and duties under this subchapter and within the limitation of funds appropriated specifically for such purpose, engage in and contribute to the cost of research and other projects of mutual interest undertaken by such agencies, and utilize the services of such agencies and their employees, and, notwithstanding any other provision of law, pay by advance or reimbursement such agencies and their employees for services rendered to assist the Commission in carrying out this subchapter. In furtherance of such cooperative efforts, the Commission may enter into written agreements with such State or local agencies and such agreements may include provisions under which the Commission shall refrain from processing a charge in any cases or class of cases specified in such agreements or under which the Commission shall relieve any person or class of persons in such State or locality from requirements imposed under this section. The Commission shall rescind any such agreement whenever it determines that the agreement no longer serves the interest of effective enforcement of this subchapter."],[0,"(c) Execution, retention, and preservation of records; reports to Commission; training program records; appropriate relief from regulation or order for undue hardship; procedure for exemption; judicial action to compel compliance"],[0,"Every employer, employment agency, and labor organization subject to this subchapter shall (1) make and keep such records relevant to the determinations of whether unlawful employment practices have been or are being committed, (2) preserve such records for such periods, and (3) make such reports therefrom as the Commission shall prescribe by regulation or order, after public hearing, as reasonable, necessary, or appropriate for the enforcement of this subchapter or the regulations or orders thereunder. The Commission shall, by regulation, require each employer, labor organization, and joint labor-management committee subject to this subchapter which controls an apprenticeship or other training program to maintain such records as are reasonably necessary to carry out the purposes of this subchapter, including, but not limited to, a list of applicants who wish to participate in such program, including the chronological order in which applications were received, and to furnish to the Commission upon request, a detailed description of the manner in which persons are selected to participate in the apprenticeship or other training program. Any employer, employment agency, labor organization, or joint labor-management committee which believes that the application to it of any regulation or order issued under this section would result in undue hardship may apply to the Commission for an exemption from the application of such regulation or order, and, if such application for an exemption is denied, bring a civil action in the United States district court for the district where such records are kept. If the Commission or the court, as the case may be, finds that the application of the regulation or order to the employer, employment agency, or labor organization in question would impose an undue hardship, the Commission or the court, as the case may be, may grant appropriate relief. If any person required to comply with the provisions of this subsection fails or refuses to do so, the United States district court for the district in which such person is found, resides, or transacts business, shall, upon application of the Commission, or the Attorney General in a case involving a government, governmental agency or political subdivision, have jurisdiction to issue to such person an order requiring him to comply."],[0,"(d) Consultation and coordination between Commission and interested State and Federal agencies in prescribing recordkeeping and reporting requirements; availability of information furnished pursuant to recordkeeping and reporting requirements; conditions on availability"],[0,"In prescribing requirements pursuant to subsection (c) of this section, the Commission shall consult with other interested State and Federal agencies and shall endeavor to coordinate its requirements with those adopted by such agencies. The Commission shall furnish upon request and without cost to any State or local agency charged with the administration of a fair employment practice law information obtained pursuant to subsection (c) of this section from any employer, employment agency, labor organization, or joint labor-management committee subject to the jurisdiction of such agency. Such information shall be furnished on condition that it not be made public by the recipient agency prior to the institution of a proceeding under State or local law involving such information. If this condition is violated by a recipient agency, the Commission may decline to honor subsequent requests pursuant to this subsection."],[0,"(e) Prohibited disclosures; penalties"],[0,"It shall be unlawful for any officer or employee of the Commission to make public in any manner whatever any information obtained by the Commission pursuant to its authority under this section prior to the institution of any proceeding under this subchapter involving such information. Any officer or employee of the Commission who shall make public in any manner whatever any information in violation of this subsection shall be guilty, of a misdemeanor and upon conviction thereof, shall be fined not more than $1,000, or imprisoned not more than one year."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e-8?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2000e–8. Investigations","tname":"The Public Health and Welfare","by":{"0":""}}]};